<script setup lang="ts">
import { t as uiText } from '@/locales'

import {onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useUserStore} from '@/stores/user'
import {newRequestId} from '@/api/modules/partner'
import {sampleIdentityColors,previewSampleColor,sampleIdentityAction,type SampleColorChoice,type SampleColorPreview} from '@/api/modules/sampleManagement'
import type {SampleIdentity} from '@/types/sampleManagement'
import {useSampleSubmission} from './useSampleSubmission'
const props=defineProps<{sample:SampleIdentity}>(),emit=defineEmits<{close:[];saved:[value:SampleIdentity]}>(),user=useUserStore(),auth=user.token
const {busy,error,unknown,submit}=useSampleSubmission('color:'+props.sample.sampleIdentityId),choices=ref<SampleColorChoice[]>([]),color=ref(''),reason=ref(''),preview=ref<SampleColorPreview>(),confirmMerge=ref(false),loading=ref(true)
const requestId=newRequestId();let disposed=false
onMounted(async()=>{try{const result=await sampleIdentityColors(props.sample.sampleIdentityId);if(!disposed&&auth===user.token)choices.value=result.content}catch(e){error.value=e instanceof Error?e.message:'读取原供方颜色失败'}finally{loading.value=false}})
watch([color,reason],()=>{preview.value=undefined;confirmMerge.value=false});watch(()=>user.token,()=>emit('close'));onBeforeUnmount(()=>{disposed=true})
const input=()=>({colorName:color.value.trim(),...(choices.value.some(c=>'id:'+c.id===color.value)?{colorId:Number(color.value.slice(3)),colorName:choices.value.find(c=>'id:'+c.id===color.value)!.name}:{}),reason:reason.value.trim()})
async function prepare(){if(!color.value.trim()||!reason.value.trim()){error.value='请填写正确颜色和更正原因';return}busy.value=true;error.value='';try{const value=await previewSampleColor(props.sample.sampleIdentityId,input());if(!disposed&&auth===user.token)preview.value=value}catch(e){error.value=e instanceof Error?e.message:'颜色核对失败'}finally{busy.value=false}}
async function save(){if(!unknown.value&&(!preview.value||(preview.value.targetIdentityId>0&&preview.value.targetIdentityId!==props.sample.sampleIdentityId&&!confirmMerge.value))){error.value='请先预览，并确认已有同色样品归属';return}const value=await submit(()=>({...input(),version:preview.value!.version,requestId,targetIdentityId:preview.value!.targetIdentityId,confirmSameType:confirmMerge.value}),payload=>sampleIdentityAction(props.sample.sampleIdentityId,'correct_color',payload));if(value&&!disposed&&auth===user.token)emit('saved',value)}
function close(){if(!busy.value&&!unknown.value)emit('close')}
</script>
<template><el-dialog class="sample-color-dialog" :model-value="true" :title='uiText("更正录错的样品颜色")' width="min(660px,96vw)" append-to-body :close-on-click-modal="false" :before-close="close"><div v-loading="loading"><p>{{sample.sampleCode}} · {{sample.name}} · {{sample.phoneName||sample.specName}}</p><el-form label-position="top" :disabled="busy||unknown||loading"><el-form-item :label='uiText("原颜色")'><strong>{{sample.colorName||uiText('未填写')}}</strong></el-form-item><el-form-item :label='uiText("正确颜色 *")'><el-select v-model="color" filterable allow-create default-first-option :placeholder='uiText("选择原供方颜色，也可直接填写")' :aria-label='uiText("更正后的颜色")'><el-option v-for="choice in choices" :key="choice.id" :value="'id:'+choice.id" :label="choice.name+(choice.supplierColorCode?' · '+choice.supplierColorCode:'')"/></el-select></el-form-item><el-form-item :label='uiText("更正原因 *")'><el-input v-model="reason" type="textarea" autosize :placeholder='uiText("例如：收样时误填黑色，实物为紫色")' :aria-label='uiText("颜色更正原因")'/></el-form-item></el-form><div v-if="preview" class="color-preview"><strong>{{preview.before.name||uiText('未填写')}} → {{preview.after.name}}</strong><p>{{ uiText("更正 ") }}{{preview.batchCount}}{{ uiText(" 个原收样批次的当前颜色，库存和借还数量保持原值；原收样及寄样资料保留。") }}</p><template v-if="preview.targetIdentityId&&preview.targetIdentityId!==sample.sampleIdentityId"><p>{{ uiText("已存在同色样品：") }}{{preview.targetSampleCode}}{{ uiText("。原样品码保留查询入口。") }}</p><el-checkbox v-model="confirmMerge" :disabled="busy||unknown">{{ uiText("确认实物相同，将本样品批次归入 ") }}{{preview.targetSampleCode}}</el-checkbox></template></div><el-alert v-if="error" :title="error" type="error" :closable="false"/></div><template #footer><el-button :disabled="busy||unknown" @click="close">{{ uiText("取消") }}</el-button><el-button v-if="!unknown" :loading="busy" :disabled="loading" @click="prepare">{{ uiText("预览更正") }}</el-button><el-button type="primary" :loading="busy" :disabled="!unknown&&!preview" @click="save">{{unknown?uiText('核对本次保存结果'):uiText('确认更正')}}</el-button></template></el-dialog></template>
<style scoped>p{font-size:12px;line-height:1.7;overflow-wrap:anywhere}.el-select{width:100%}.color-preview{padding:10px;background:#f1f6fc;font-size:12px;margin-bottom:10px}.color-preview .el-checkbox{height:auto;white-space:normal}:global(.sample-color-dialog){max-height:calc(100dvh - 40px);margin-block:20px;overflow:auto}</style>
